<script setup lang="ts">
import { onMounted, onUnmounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import RecordDelete from './RecordDelete.vue'
import { api, beijingTime } from './api'
import { errorMessage, statusLabel, requestKey, type Job, type Settings } from './monitoring'
const page=ref(1),total=ref(0)
const checked=ref<Job[]>([]),deletion=ref<InstanceType<typeof RecordDelete>>()
const route = useRoute(), router = useRouter(), items = ref<Job[]>([]), job = ref<Job>(), logs = ref<{ id: number; time: number; message: string }[]>([]), error = ref(''), busy = ref(false)
let disposed=false, cursor = 0, generation = 0, timer: ReturnType<typeof setInterval> | undefined
async function load() { if (disposed || document.hidden || busy.value) return; busy.value = true; const current = generation; try { const id = route.params.id; if (id) { const data = await api<{ job: Job; logs: typeof logs.value; cursor: number }>(`/api/deployments/${id}?cursor=${cursor}`); if (current === generation && !disposed) { job.value = data.job; logs.value.push(...data.logs); if (logs.value.length > 1000) logs.value.splice(0, logs.value.length - 1000); cursor = data.cursor } } else { const data = await api<{ items: Job[];total:number }>(`/api/deployments?page=${page.value}`); if (current === generation && !disposed)  {items.value = data.items;total.value=data.total;if(page.value>Math.max(1,Math.ceil(data.total/20))){page.value=Math.max(1,Math.ceil(data.total/20));generation++}} } if(current===generation && !disposed)error.value = '' } catch (e) { if(current===generation && !disposed)error.value = errorMessage(e) } finally { busy.value = false; if (!disposed && current !== generation) void load() } }
async function action(kind: string) { if (!job.value) return; try { if(job.value.kind==='remove-nodes'){const next=await api<{id:string}>('/api/servers/remove/continue','POST',{job:job.value.id});await router.push(`/deployments/${next.id}`);void load();return} const settings = await api<Settings>('/api/settings'); const next = await api<Job>('/api/deployments', 'POST', { request_key: requestKey(), revision: settings.revision, kind: job.value.kind === 'migrate' && kind === 'resume' ? 'migrate' : kind, node: job.value.node }); await router.push(`/deployments/${next.id}`) } catch (e) { error.value = errorMessage(e) } }
watch(() => route.fullPath, () => { generation++; cursor = 0; logs.value = []; job.value = undefined; void load() })
function visibility() { if (!document.hidden) void load() }
onMounted(() => { void load(); timer = setInterval(load, 2000); document.addEventListener('visibilitychange', visibility) })
onUnmounted(() => { disposed=true; generation++; clearInterval(timer); document.removeEventListener('visibilitychange', visibility) })
</script>
<template><el-alert v-if="error" :title="error" type="warning" :closable="false" /><el-card shadow="never" v-if="!route.params.id"><RecordDelete ref="deletion" :records="checked" label="部署任务历史" endpoint="/api/deployments/delete" @done="load"/><el-table :data="items" @selection-change="checked=$event" empty-text="暂无后台部署任务"><el-table-column type="selection" :selectable="(row:Job)=>!!row.can_delete" width="48"/><el-table-column label="任务" min-width="200"><template #default="{ row }"><router-link :to="`/deployments/${row.id}`">{{ row.kind }} · {{ row.node || '主服务器 / 配置范围' }}</router-link></template></el-table-column><el-table-column label="状态"><template #default="{ row }">{{ statusLabel(row.status) }}</template></el-table-column><el-table-column label="开始时间" min-width="190"><template #default="{ row }">{{ beijingTime(row.created) }}</template></el-table-column><el-table-column prop="message" label="结果" min-width="220" /><el-table-column label="删除保护" min-width="220"><template #default="{row}"><el-button link type="danger" :disabled="!row.can_delete" @click="deletion?.open([row])">删除</el-button><small class="muted">{{row.delete_reason}}</small></template></el-table-column></el-table><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="total,prev,pager,next" @change="checked=[];load()"/></el-card><template v-else><el-card shadow="never"><h3>{{ job?.kind }} · {{ statusLabel(job?.status || 'queued') }}</h3><p>{{ job?.message || '任务在宿主机执行，关闭页面不会终止。后台重启时会自动重新连接。' }}</p><div class="filters"><router-link to="/deployments">返回任务列表</router-link><el-button v-if="job && ['failed','interrupted'].includes(job.status)" type="primary" @click="action('resume')">继续原任务</el-button><el-button v-if="job && ['failed','interrupted'].includes(job.status) && !['migrate','remove-nodes'].includes(job.kind)" @click="action('rollback')">回退原任务</el-button></div></el-card><el-card shadow="never"><h3>执行日志</h3><pre class="task-log">{{ logs.map(log => log.message).join('') || '正在等待任务输出…' }}</pre></el-card></template></template>
<style scoped>.task-log{white-space:pre-wrap;overflow-wrap:anywhere;background:#112038;color:#dae6fa;padding:20px;border-radius:8px;max-height:65vh;overflow:auto;font:13px/1.7 monospace}</style>
